    "kernel_code": "1: \"\"\"Single-rounding per-channel integer requantization.\n2: \n3: Original synthetic Triton implementation of a fixed-point GEMM epilogue.\n4: The task specifies exact compatibility with the stated single-rounding rule.\n5: This file is not an upstream kernel or a historical bug reproduction.\n6: \"\"\"\n7: import torch\n8: import triton\n9: import triton.language as tl\n10: import triton.language.extra.cuda.libdevice as libdevice\n11: \n12: \n13: @triton.jit\n14: def _rescale_scalar(a, m, r, z):\n15:     product = a.to(tl.float64) * m.to(tl.float64)\n16:     denominator = (tl.full((), 1, tl.int64) << (31 + r)).to(tl.float64)\n17:     scaled = libdevice.div_rn(product, denominator)\n18:     rounded = libdevice.floor(scaled + 0.5).to(tl.int64)\n19:     bounded = tl.minimum(tl.maximum(rounded, -255), 255).to(tl.int32)\n20:     return tl.minimum(tl.maximum(bounded + z, -128), 127).to(tl.int8)\n21: \n22: \n23: @triton.jit\n24: def _requantize(ACC, MULT, SHIFT, ZERO, OUT,\n25:                 ROWS: tl.constexpr, CHANNELS: tl.constexpr, BLOCK: tl.constexpr):\n26:     index = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n27:     active = index < ROWS * CHANNELS\n28:     channel = index % CHANNELS\n29:     a = tl.load(ACC + index, mask=active, other=0)\n30:     m = tl.load(MULT + channel, mask=active, other=1073741824)\n31:     r = tl.load(SHIFT + channel, mask=active, other=0)\n32:     z = tl.load(ZERO + channel, mask=active, other=0)\n33:     value = _rescale_scalar(a, m, r, z)\n34:     tl.store(OUT + index, value, mask=active)\n35: \n36: \n37: def validate_inputs(acc, multipliers, right_shifts, zero_points, require_cuda=True):\n38:     def require(condition, message):\n39:         if not condition:\n40:             raise ValueError(message)\n41:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n42:     buffers = (acc, multipliers, right_shifts, zero_points)\n43:     for tensor in buffers:\n44:         require(type(tensor) is torch.Tensor, \"ordinary torch.Tensor required\")\n45:         require(tensor.layout == torch.strided and tensor.is_contiguous(),\n46:                 \"contiguous strided tensors required\")\n47:         require(not tensor.requires_grad and not tensor.is_inference(),\n48:                 \"ordinary non-gradient buffers required\")\n49:         require(not tensor.is_neg() and not tensor.is_conj(), \"logical view flags excluded\")\n50:         require(not require_cuda or tensor.is_cuda, \"CUDA tensors required by run\")\n51:         require(tensor.dtype == torch.int32, \"all inputs must be int32\")\n52:     require(all(t.device == acc.device for t in buffers), \"one device required\")\n53:     require(acc.ndim == 2, \"acc must have shape [M,C]\")\n54:     rows, channels = acc.shape\n55:     require(1 <= rows <= 4096 and 1 <= channels <= 257,\n56:             \"M must be 1..4096 and C must be 1..257\")\n57:     for tensor in buffers[1:]:\n58:         require(tensor.shape == (channels,), \"channel parameters must have shape [C]\")\n59:     require(bool((multipliers >= (1 << 30)).all().item()), \"multipliers must be 2^30..2^31-1\")\n60:     require(bool(((right_shifts >= 0) & (right_shifts <= 31)).all().item()),\n61:             \"right shifts must be 0..31\")\n62:     require(bool(((zero_points >= -128) & (zero_points <= 127)).all().item()),\n63:             \"zero points must be -128..127\")\n64:     return {\"valid\": True, \"rows\": rows, \"channels\": channels}\n65: \n66: \n67: def run(acc, multipliers, right_shifts, zero_points):\n68:     validate_inputs(acc, multipliers, right_shifts, zero_points)\n69:     rows, channels = acc.shape\n70:     with torch.cuda.device(acc.device):\n71:         output = torch.empty((rows, channels), dtype=torch.int8, device=acc.device)\n72:         _requantize[(triton.cdiv(rows * channels, 128),)](\n73:             acc, multipliers, right_shifts, zero_points, output,\n74:             ROWS=rows, CHANNELS=channels, BLOCK=128, num_warps=4,\n75:             enable_fp_fusion=False)\n76:     return output\n77: \n78: \n79: def reference(acc, multipliers, right_shifts, zero_points):\n80:     \"\"\"Direct single-rounding definition, with exact signed int64 arithmetic.\"\"\"\n81:     validate_inputs(acc, multipliers, right_shifts, zero_points, require_cuda=False)\n82:     a = acc.cpu().to(torch.int64)\n83:     m = multipliers.cpu().to(torch.int64)\n84:     r = right_shifts.cpu().to(torch.int64)\n85:     z = zero_points.cpu().to(torch.int64)\n86:     product = a * m\n87:     bias = torch.bitwise_left_shift(torch.ones_like(r), 30 + r)\n88:     rounded = torch.bitwise_right_shift(product + bias, 31 + r)\n89:     return torch.clamp(rounded + z, -128, 127).to(torch.int8).to(acc.device)\n90: \n91: \n92: def make_inputs(device=\"cuda\", rows=37, channels=65, seed=0):\n93:     \"\"\"Example generator; every int32 accumulator belongs to the public domain.\"\"\"\n94:     g = torch.Generator(device=\"cpu\").manual_seed(seed)\n95:     a = torch.randint(-(1 << 31), 1 << 31, (rows, channels),\n96:                       generator=g, dtype=torch.int64).to(torch.int32)\n97:     m = torch.randint(1 << 30, 1 << 31, (channels,), generator=g,\n98:                       dtype=torch.int64).to(torch.int32)\n99:     r = torch.randint(0, 32, (channels,), generator=g, dtype=torch.int32)\n100:     z = torch.randint(-128, 128, (channels,), generator=g, dtype=torch.int32)\n101:     return tuple(t.to(device) for t in (a, m, r, z))",
